import { useNavigate } from 'react-router-dom'
import HomeBannerStrell from '../../../../components/UI/HomeBannerStrell/HomeBannerStrell'
import Styles from './HomeBanersStyle.module.scss'
import { useGlobal } from '@/context/GlobalContext'


const HomeBaners = () =>{
    const navigate = useNavigate()

    const {setFilters} = useGlobal()

    const changePage = (room) =>{
        navigate('/Shop')
        setFilters(room)
        window.scrollTo({top:0, behavior:'smooth'})
    }

    return(
            <div className={Styles.Home_Baner}>
                <div className={Styles['Home_Baner_Big-Card']}  onClick={() => changePage('Living Room')}>
                    <h2>Living Room</h2>
                    <HomeBannerStrell text='Shop Now'/>
                </div>

                <div className={Styles['Home_Baner_Small-Card']}>
                    <div className={`${Styles['Home_Baner_Small-Top']} ${Styles['Home_Baner-Small-element']}`} onClick={() => changePage('Bedroom')}>
                        <h2>Bedroom</h2>
                        <HomeBannerStrell text='Shop Now'/>
                    </div>
                
                    <div className={`${Styles['Home_Baner_Small-Bottom']} ${Styles['Home_Baner-Small-element']}`} onClick={() => changePage('Kitchen')}>
                    <h2>Kitchen</h2>
                        <HomeBannerStrell text='Shop Now'/>
                    </div>
                </div>
            </div>
    )
}

export default HomeBaners